210	// ─── Event Handlers ───
211	// Modules register handlers that execute when specific events fire in handleEventForGoals.
212	// Each handler receives the event and a context with agents, goalManager, etc.
213	import type { WorldEvent, ConsequenceRule } from './cg-types';
214	import type { ILEffect } from './il';
215	import type { GoalManager } from './goals';
216	import type { NpcGoal, GoalStep, GoalActionResult } from './goals';
217	import type { CrimeScene, LocationGraph } from './world-types';
218	import type { ExaminationPoint } from './world-types';
219	import type { EvidenceLayer } from './evidence';
220	import type { IEventStore } from './event-types';
221	
222	export interface EventHandlerContext {
223	  agents: Map<string, Agent>;
224	  goalManager: GoalManager;
225	  crimeScenes: Map<string, CrimeScene[]>;
226	  getCurrentDay: () => number;
227	  /** Body discovery tracking — module can mark bodies as discovered to prevent re-discovery loops */
228	  bodyDiscoveries: Set<string>;
229	  /** Trigger reactive affordance evaluation for a specific NPC on this event. Engine handles AL mechanics. */
230	  triggerReactiveEvaluation: (npcId: string, event: WorldEvent) => Promise<void>;
231	  /** Add a mood modifier to an NPC (SPEC-mood-modifiers) */
232	  addMoodModifier: MoodModifierCallback;
233	}
234	
235	export type EventHandlerFn = (event: WorldEvent, ctx: EventHandlerContext) => void | Promise<void>;
236	
237	const EVENT_HANDLERS: Map<string, EventHandlerFn[]> = new Map();
238	
239	export function registerEventHandler(eventType: string, handler: EventHandlerFn): void {
240	  if (!eventType) throw new Error(`[EventHandler] Empty event type`);
241	  if (typeof handler !== 'function') throw new Error(`[EventHandler] Handler for '${eventType}' is not a function`);
242	  const handlers = EVENT_HANDLERS.get(eventType) ?? [];
243	  handlers.push(handler);
244	  EVENT_HANDLERS.set(eventType, handlers);
245	}
246	
247	export function getEventHandlers(eventType: string): EventHandlerFn[] {
248	  return EVENT_HANDLERS.get(eventType) ?? [];
249	}
