1	import { getBeliefSourceLabel, getSourceTransferWeight, getSourceDecayRate, getEventTypeDecayRate, getEventLabel } from './event-registry';
2	
3	// BeliefSource is a string — modules can add new sources via registry
4	export type BeliefSource = string;
5	
6	export interface Belief {
7	  id: string;
8	  /** Event type: "NPC_KILLED", etc. */
9	  eventType: string;
10	  /** Who did it (null if unknown) */
11	  subject: string | null;
12	  /** Who was it done to (null if unknown) */
13	  object: string | null;
14	  /** Where it happened (null if unknown) */
15	  location: string | null;
16	  /** 0.0 - 1.0 */
17	  confidence: number;
18	  /** How the NPC learned this */
19	  source: BeliefSource;
20	  /** Who told them (null if witnessed directly) */
21	  sourceNpcId: string | null;
22	  /** Game day when formed */
23	  gameDay: number;
24	  /** Game day when last reinforced */
25	  lastUpdated: number;
26	}
27	
28	/** Default confidence by source type */
29	export const SOURCE_CONFIDENCE: Record<BeliefSource, number> = {
30	  witness: 0.95,
31	  body_discovery: 0.7,
32	  testimony: 0.6,
33	  rumor: 0.4,
34	  interrogation: 0.7,
35	  observation: 0.8,
36	  cover_up: 0.95,
37	  deduction: 0.5,
38	  evidence: 0.5,
39	  perpetrator: 1.0,
40	};
41	
42	export class BeliefManager {
43	  private beliefs: Map<string, Belief> = new Map();
44	
45	  addBelief(belief: Belief): void {
46	    // Contract guard
47	    if (!belief.id) throw new Error(`[Belief] Missing id for ${belief.eventType}`);
48	    if (!belief.eventType) throw new Error(`[Belief] Missing eventType`);
49	    if (!belief.source) throw new Error(`[Belief] Missing source for ${belief.eventType}`);
50	    if (typeof belief.confidence !== 'number' || belief.confidence < 0 || belief.confidence > 1) {
51	      throw new Error(`[Belief] Invalid confidence ${belief.confidence} for ${belief.eventType}`);
52	    }
53	    // Check for existing belief about same event+object+source — reinforce instead of duplicate.
54	    // Different sources create separate beliefs (observation vs evidence vs testimony = coexist).
55	    // Same source about same event+object = merge (two testimonies about same crime reinforce).
56	    const existing = this.findExisting(belief.eventType, belief.object, belief.source);
57	    if (existing) {
58	      // Take the higher confidence, update sourceNpcId if new is more direct
59	      if (belief.confidence > existing.confidence) {
60	        existing.confidence = belief.confidence;
61	        existing.sourceNpcId = belief.sourceNpcId;
62	      }
63	      // Update subject if we now have a specific suspect (replace null)
64	      if (belief.subject && !existing.subject) {
65	        existing.subject = belief.subject;
66	        existing.confidence = Math.max(existing.confidence, belief.confidence);
67	      }
68	      existing.lastUpdated = belief.gameDay;
69	      return;
70	    }
71	    this.beliefs.set(belief.id, belief);
72	  }
73	
74	  /** Find existing belief about same event type, object, AND source */
75	  private findExisting(eventType: string, object: string | null | undefined, source: string): Belief | null {
76	    for (const b of this.beliefs.values()) {
77	      if (b.eventType === eventType && b.object === object && b.source === source) return b;
78	    }
79	    return null;
80	  }
81	
82	  /** Get max confidence across ALL beliefs about a suspect for a given event category */
83	  getMaxConfidenceFor(subject: string, eventTypeMatcher?: (eventType: string) => boolean): number {
84	    let max = 0;
85	    for (const b of this.beliefs.values()) {
86	      if (b.subject !== subject) continue;
87	      if (eventTypeMatcher && !eventTypeMatcher(b.eventType)) continue;
88	      if (b.confidence > max) max = b.confidence;
89	    }
90	    return max;
91	  }
92	
93	  queryBeliefs(filter: {
94	    eventType?: string;
95	    subject?: string;
96	    object?: string;
97	  }): Belief[] {
98	    const results: Belief[] = [];
99	    for (const b of this.beliefs.values()) {
100	      if (filter.eventType && b.eventType !== filter.eventType) continue;
101	      if (filter.subject && b.subject !== filter.subject) continue;
102	      if (filter.object && b.object !== filter.object) continue;
103	      results.push(b);
104	    }
105	    return results.sort((a, b) => b.confidence - a.confidence);
106	  }
107	
108	  /** Decay all beliefs per day advance. Rumors fade faster, direct evidence holds longer. */
109	  decayBeliefs(currentDay: number): void {
110	    for (const b of this.beliefs.values()) {
111	      const daysSince = currentDay - b.lastUpdated;
112	      if (daysSince > 0) {
113	        const sourceRate = getSourceDecayRate(b.source);
114	        if (sourceRate === 0) continue; // source never decays (e.g. secret knowledge)
115	        const effectiveRate = sourceRate * getEventTypeDecayRate(b.eventType);
116	        b.confidence = Math.max(0.1, b.confidence - effectiveRate * daysSince);
117	      }
118	    }
119	  }
120	
121	  getStrongestBelief(eventType: string, object: string): Belief | null {
122	    let best: Belief | null = null;
123	    for (const b of this.beliefs.values()) {
124	      if (b.eventType !== eventType) continue;
125	      if (b.object !== object) continue;
126	      if (!best || b.confidence > best.confidence) best = b;
127	    }
128	    return best;
129	  }
130	
131	  getAllBeliefs(): Belief[] {
132	    return Array.from(this.beliefs.values()).sort((a, b) => b.confidence - a.confidence);
133	  }
134	
135	  /** Compact summary for LLM system prompt (2nd person: "You certain: X committed...") */
136	  summarizeForPrompt(maxBeliefs = 3, nameResolver?: (id: string) => string): string {
137	    const resolveName = nameResolver ?? ((id: string) => id);
138	    const beliefs = this.getAllBeliefs()
139	      .filter(b => b.object != null || b.subject != null)
140	      .slice(0, maxBeliefs);
141	    if (beliefs.length === 0) return '';
142	
143	    return beliefs.map((b) => {
144	      const certainty = b.confidence > 0.8 ? 'certain' : b.confidence > 0.5 ? 'believe' : 'heard rumor';
145	      const verb = getEventLabel(b.eventType);
146	      if (!verb) return null;
147	      const who = b.subject ? resolveName(b.subject) : 'someone unknown';
148	      const target = b.object ? resolveName(b.object) : 'someone';
149	      const where = b.location ? ` at ${b.location}` : '';
150	      const how = getBeliefSourceLabel(b.source);
151	      return `- You ${certainty}: ${who} committed ${verb} against ${target}${where} (${how})`;
152	    }).filter(Boolean).join('\n');
153	  }
154	
155	  /**
156	   * 3rd person summary for conversation memories (stored in OTHER NPC's memory).
157	   * Optional eventTypeFilter: only include beliefs matching the conversation topic's eventType.
158	   * Falls back to top beliefs by confidence if filter yields nothing.
159	   */
160	  summarizeForMemory(ownerName: string, maxBeliefs = 2, eventTypeFilter?: string, nameResolver?: (id: string) => string): string {
161	    const resolveName = nameResolver ?? ((id: string) => id);
162	    const all = this.getAllBeliefs()
163	      .filter(b => b.object != null || b.subject != null);
164	
165	    // Prefer beliefs matching topic eventType; fall back to top by confidence
166	    let beliefs = eventTypeFilter
167	      ? all.filter(b => b.eventType === eventTypeFilter).slice(0, maxBeliefs)
168	      : [];
169	    if (beliefs.length === 0) beliefs = all.slice(0, maxBeliefs);
170	    if (beliefs.length === 0) return '';
171	
172	    return beliefs.map((b) => {
173	      const conf = b.confidence > 0.7 ? 'is convinced' : b.confidence > 0.4 ? 'believes' : 'has heard';
174	      const verb = getEventLabel(b.eventType);
175	      if (!verb) return null;
176	      const who = b.subject ? resolveName(b.subject) : 'someone';
177	      const target = b.object ? resolveName(b.object) : 'someone';
178	      return `${ownerName} ${conf} ${who} committed ${verb} against ${target}`;
179	    }).filter(Boolean).join('. ');
180	  }
181	
182	  /** Serializable snapshot */
183	  toJSON(): Belief[] {
184	    return this.getAllBeliefs();
185	  }
186	
187	  /** Restore from saved snapshot — validates fields, skips corrupted entries */
188	  static fromJSON(data: Belief[]): BeliefManager {
189	    const manager = new BeliefManager();
190	    for (const belief of data) {
191	      if (!belief.id || !belief.eventType || !belief.source) {
192	        console.warn(`  [Save] Skipping belief with missing fields: id=${belief.id}, type=${belief.eventType}, source=${belief.source}`);
193	        continue;
194	      }
195	      if (typeof belief.confidence !== 'number' || belief.confidence < 0 || belief.confidence > 1) {
196	        console.warn(`  [Save] Clamping invalid confidence ${belief.confidence} for belief ${belief.id}`);
197	        belief.confidence = Math.max(0, Math.min(1, Number(belief.confidence) || 0));
198	      }
199	      manager.beliefs.set(belief.id, belief);
200	    }
201	    return manager;
202	  }
203	}
