137	/**
138	 * Transfer transferable beliefs from sender to receiver.
139	 * Dedup by (eventType, object) per Invariant 14.
140	 */
141	function transferBeliefs(
142	  sender: Agent,
143	  receiver: Agent,
144	  senderId: string,
145	  gameDay: number,
146	): BeliefTransferResult {
147	  const transferred: BeliefTransferResult['transferred'] = [];
148	  if (!sender.state.beliefs || !receiver.state.beliefs) return { transferred };
149	
150	  const senderBeliefs = sender.state.beliefs.getAllBeliefs();
151	  const crimeBeliefs = senderBeliefs.filter(
152	    (b) => isTransferable(b.eventType) && b.confidence >= 0.3,
153	  );
154	
155	  for (const b of crimeBeliefs) {
156	    const transferConfidence = b.confidence * getSourceTransferWeight(b.source);
157	
158	    // Dedup by (eventType, object) — Invariant 14
159	    const existing = receiver.state.beliefs.getAllBeliefs().find(
160	      (eb) => eb.eventType === b.eventType && eb.object === b.object,
161	    );
162	    if (existing && existing.confidence >= transferConfidence) continue;
163	
164	    receiver.state.beliefs.addBelief({
165	      id: crypto.randomUUID(),
166	      eventType: b.eventType,
167	      subject: b.subject,
168	      object: b.object,
169	      location: b.location,
170	      confidence: transferConfidence,
171	      source: BELIEF_SOURCE.TESTIMONY,
172	      sourceNpcId: senderId,
173	      gameDay,
174	      lastUpdated: gameDay,
175	    });
176	    transferred.push({ eventType: b.eventType, subject: b.subject, object: b.object });
177	  }
178	
179	  return { transferred };
180	}
