671	  // Step handlers for steal_from, attack_npc, arrest_npc, destroy_evidence, flee,
672	  // examine_scene, sentence_npc moved to modules/crime-justice/step-handlers.ts
673	
674	  private findInteractCandidates(
675	    ownerId: string,
676	    owner: Agent,
677	    agents: Map<string, Agent>,
678	    filter: NpcFilter | undefined,
679	    alreadyInteracted: string[],
680	  ): [string, Agent][] {
681	    const interactedSet = new Set(alreadyInteracted);
682	    const excludeIds = new Set(filter?.excludeIds ?? []);
683	
684	    return Array.from(agents.entries()).filter(([id, agent]) => {
685	      if (id === ownerId) return false;
686	      if (agent.profile.isPlayer) return false; // Player not a valid NPC-NPC interaction target
687	      if (interactedSet.has(id)) return false;
688	      if (excludeIds.has(id)) return false;
689	      if (filter?.onlyAlive !== false && !agent.state.alive) return false;
690	      if (agent.state.location !== owner.state.location) return false;
691	      // role-based filtering removed (INV-14: use capability flags, not role strings)
692	      return true;
693	    });
694	  }
695	}
