1039	function setAffordanceCooldown(ctx: AffordanceContext, npcId: string, affordanceId: string, gameMinute: number, aff?: AffordanceDefinition): void {
1040	  if (!ctx.cooldowns || !affordanceId) return;
1041	  let npcMap = ctx.cooldowns.get(npcId);
1042	  if (!npcMap) {
1043	    npcMap = new Map();
1044	    ctx.cooldowns.set(npcId, npcMap);
1045	  }
1046	  const cooldown = aff?.cooldownOverride ?? ctx.affordanceCooldownMinutes ?? DEFAULT_AFFORDANCE_COOLDOWN;
1047	  npcMap.set(affordanceId, gameMinute + cooldown);
1048	}
