384	// ─── Target Finding (Proactive) ───
385	
386	function findTarget(
387	  aff: AffordanceDefinition,
388	  npcId: string,
389	  agent: Agent,
390	  ctx: AffordanceContext,
391	): AffordanceTarget | null {
392	  // Generic role-based finder takes priority (declarative, no custom code needed)
393	  if (aff.targetRole) return findByRole(aff.targetRole, npcId, agent, ctx);
394	  const key = aff.targetFinder ?? aff.id;
395	  const finder = TARGET_FINDERS.get(key);
396	  return finder ? finder(npcId, agent, ctx, aff) : null;
397	}
