20	export class ConsequenceEngine {
21	  /** Trigger index: event type → rules that fire on it. O(1) lookup. */
22	  private rulesByTrigger = new Map<string, ConsequenceRule[]>();
23	  private onEvent?: (event: WorldEvent) => void;
24	
25	  constructor(rules: ConsequenceRule[], options?: EngineOptions) {
26	    this.onEvent = options?.onEvent;
27	    // Build trigger index
28	    for (const rule of rules) {
29	      const existing = this.rulesByTrigger.get(rule.trigger);
30	      if (existing) {
31	        existing.push(rule);
32	      } else {
33	        this.rulesByTrigger.set(rule.trigger, [rule]);
34	      }
35	    }
36	  }
37	
38	  /**
39	   * Process an event through all rules, then cascade:
40	   * consequences can trigger further rules up to maxChainDepth.
41	   */
42	  async process(
43	    event: WorldEvent,
44	    ctx: WorldContext,
45	    depth: number = 0,
46	  ): Promise<ConsequenceResult[]> {
47	    const MAX_GLOBAL_DEPTH = 10;
48	    if (depth >= MAX_GLOBAL_DEPTH) return [];
49	
50	    // Track witnesses across the entire chain to avoid duplicates
51	    if (!ctx.witnessIds) ctx.witnessIds = new Set();
52	
53	    const candidates = this.rulesByTrigger.get(event.type) ?? [];
54	    const depthFiltered = candidates.filter(r => depth < r.maxChainDepth);
55	
56	    // ─── Separate exclusive vs independent rules ───
57	    const independent: ConsequenceRule[] = [];
58	    const exclusiveGroups = new Map<string, ConsequenceRule[]>();
59	
60	    for (const rule of depthFiltered) {
61	      if (rule.exclusive) {
62	        const group = exclusiveGroups.get(rule.exclusive);
63	        if (group) {
64	          group.push(rule);
65	        } else {
66	          exclusiveGroups.set(rule.exclusive, [rule]);
67	        }
68	      } else {
69	        independent.push(rule);
70	      }
71	    }
72	
73	    // ─── Resolve which rules fire ───
74	    // Independent rules: all that pass probability + conditions
75	    const toFire: Array<{ rule: ConsequenceRule; targets: string[] }> = [];
76	
77	    for (const rule of independent) {
78	      if (rule.consequence.probability < 1.0 && Math.random() > rule.consequence.probability) continue;
79	      const targets = this.evaluateConditions(rule, event, ctx);
80	      if (targets.length > 0) toFire.push({ rule, targets });
81	    }
82	
83	    // Exclusive groups: per-target priority resolution.
84	    // Each target gets the highest-priority rule that matches them.
85	    // E.g., Ted (friend) gets cover-up, Hilda (honest) gets eager-report.
86	    for (const [, group] of exclusiveGroups) {
87	      group.sort((a, b) => (b.priority ?? 0) - (a.priority ?? 0));
88	      const claimed = new Set<string>(); // targets already assigned to higher-priority rules
89	      for (const rule of group) {
90	        if (rule.consequence.probability < 1.0 && Math.random() > rule.consequence.probability) continue;
91	        const targets = this.evaluateConditions(rule, event, ctx);
92	        // Only include targets not yet claimed by a higher-priority rule
93	        const unclaimed = targets.filter(t => !claimed.has(t));
94	        if (unclaimed.length > 0) {
95	          toFire.push({ rule, targets: unclaimed });
96	          for (const t of unclaimed) claimed.add(t);
97	        }
98	      }
99	    }
100	
101	    // ─── Fire matched rules ───
102	    const allResults: ConsequenceResult[] = [];
103	
104	    for (const { rule, targets } of toFire) {
105	      const consequenceEvent: WorldEvent = {
106	        id: crypto.randomUUID(),
107	        type: rule.consequence.type,
108	        subject: event.subject,
109	        object: event.object,
110	        location: event.location,
111	        gameDay: event.gameDay + rule.consequence.delayDays,
112	        importance: rule.consequence.importance,
113	        payload: {
114	          ...event.payload,
115	          sourceEvent: event.id,
116	          sourceRule: rule.id,
117	          affectedTargets: targets,
118	          originalEventType: (event.payload?.originalEventType as string) ?? event.type,
119	        },
120	      };
121	
122	      this.onEvent?.(consequenceEvent);
123	
124	      const moodShift = getEventMoodShift(rule.consequence.type);
125	
126	      for (const targetId of targets) {
127	        const agent = ctx.agents.get(targetId);
128	        if (!agent) continue;
129	
130	        const memoryText = this.buildMemoryText(rule, event, targetId, ctx);
131	        await agent.observe(memoryText, rule.consequence.importance);
132	        this.createBelief(rule, event, targetId, ctx);
133	
134	        // Module-registered post-handlers (grief, sentiment shift, etc.)
135	        for (const postHandler of getConsequencePostHandlers()) {
136	          postHandler({ targetId, agent, rule, event, agents: ctx.agents, addMoodModifier: ctx.addMoodModifier });
137	        }
138	
139	        if (moodShift !== 0) {
140	          ctx.addMoodModifier?.(targetId, { source: `event_${rule.consequence.type}`, category: 'event',
141	            magnitude: moodShift, remaining: 1440, duration: 1440, decay: 'exponential' });
142	        }
143	
144	        if (rule.tracksWitness) {
145	          ctx.witnessIds!.add(targetId);
146	        }
147	      }
148	
149	      const result: ConsequenceResult = { rule, targets, event: consequenceEvent };
150	      allResults.push(result);
151	
152	      // Cascade
153	      const cascaded = await this.process(consequenceEvent, ctx, depth + 1);
154	      allResults.push(...cascaded);
155	    }
156	
157	    return allResults;
158	  }
159	
160	  // ─── CG v2: Target Selection Pipeline ───
161	
162	  private evaluateConditions(
163	    rule: ConsequenceRule,
164	    event: WorldEvent,
165	    ctx: WorldContext,
166	  ): string[] {
167	    // Step 1: Resolve initial candidates via targetMode
168	    let candidates = this.resolveTargets(rule, event, ctx);
169	    if (candidates.length === 0) return [];
170	
171	    // Step 2: Apply conditions as filters or gates
172	    for (const cond of rule.conditions) {
173	      if (candidates.length === 0) return [];
174	
175	      if (this.isGateCondition(cond)) {
176	        if (!this.evaluateGate(cond, event, ctx)) return [];
177	      } else {
178	        candidates = candidates.filter(id => this.evaluateFilter(cond, id, event, ctx));
179	      }
180	    }
181	
182	    return candidates;
183	  }
184	
185	  /**
186	   * Resolve initial target candidates based on rule.targetMode.
187	   * - 'witnesses': alive agents at event location, excluding subject/object/known witnesses
188	   * - 'location': all alive agents at event location, excluding known witnesses
189	   * - 'affected': event.payload.affectedTargets (default, for chain rules)
190	   * - 'all': all alive agents
191	   */
192	  private resolveTargets(rule: ConsequenceRule, event: WorldEvent, ctx: WorldContext): string[] {
193	    const mode = rule.targetMode ?? 'affected';
194	
195	    switch (mode) {
196	      case 'witnesses':
197	        return Array.from(ctx.agents.entries())
198	          .filter(([id, agent]) =>
199	            agent.state.alive &&
200	            agent.state.location === event.location &&
201	            id !== event.object &&
202	            id !== event.subject &&
203	            !ctx.witnessIds?.has(id),
204	          )
205	          .map(([id]) => id);
206	
207	      case 'location':
208	        return Array.from(ctx.agents.entries())
209	          .filter(([id, agent]) =>
210	            agent.state.alive &&
211	            agent.state.location === event.location &&
212	            !ctx.witnessIds?.has(id),
213	          )
214	          .map(([id]) => id);
215	
216	      case 'affected':
217	        return (event.payload?.affectedTargets as string[]) ?? [];
218	
219	      case 'all':
220	        return Array.from(ctx.agents.entries())
221	          .filter(([, agent]) => agent.state.alive)
222	          .map(([id]) => id);
223	    }
224	  }
225	
226	  /**
227	   * Determine if a condition is a gate (check once, fail entire rule)
228	   * or a filter (reduce candidate list per-target).
229	   * Gate = condition references event/subject/object, not individual targets.
230	   * Filter = condition references 'target' → applied to each candidate.
231	   */
232	  private isGateCondition(cond: RuleCondition): boolean {
233	    // Event payload checks are always gates
234	    if (cond.op === 'eq' || cond.op === 'gt' || cond.op === 'lt') return true;
235	    if (cond.op === 'is_public_place') return true;
236	    // NPC-state conditions: gate if checking subject/object, filter if checking target
237	    // Default: 'target' (filter) — missing 'of'/'actor' = per-target check, not gate
238	    if (cond.op === 'trait') return (cond.of ?? 'target') !== 'target';
239	    if (cond.op === 'relationship') return (cond.actor ?? 'target') !== 'target';
240	    if (cond.op === 'belief') return (cond.of ?? 'target') !== 'target';
241	    // has_capability is always a filter (checks each target)
242	    if (cond.op === 'has_capability') return false;
243	    return false;
244	  }
245	
246	  private evaluateGate(cond: RuleCondition, event: WorldEvent, ctx: WorldContext): boolean {
247	    if (cond.op === 'is_public_place') {
248	      return ctx.publicPlaces?.has(event.location) ?? false;
249	    }
250	
251	    // Event payload comparisons
252	    if (cond.op === 'eq' || cond.op === 'gt' || cond.op === 'lt') {
253	      const fieldValue = (event as unknown as Record<string, unknown>)[cond.field!];
254	      if (cond.op === 'eq') return fieldValue === cond.value;
255	      if (cond.op === 'gt') return (fieldValue as number) > (cond.value as number);
256	      if (cond.op === 'lt') return (fieldValue as number) < (cond.value as number);
257	    }
258	
259	    // NPC-state gates (of !== 'target')
260	    if (cond.op === 'trait' && cond.of !== 'target') {
261	      const agent = this.resolveActor(cond.of!, event, ctx);
262	      return agent ? this.checkTrait(agent, cond) : false;
263	    }
264	    if (cond.op === 'relationship' && cond.actor !== 'target') {
265	      const agent = this.resolveActor(cond.actor!, event, ctx);
266	      const towardId = this.resolveToward(cond.toward!, event, ctx);
267	      return agent && towardId ? this.checkRelationship(agent, towardId, cond) : false;
268	    }
269	    if (cond.op === 'belief' && cond.of !== 'target') {
270	      const agent = this.resolveActor(cond.of!, event, ctx);
271	      return agent ? this.checkBelief(agent, event, cond) : false;
272	    }
273	
274	    console.warn(`[CG] Unknown gate condition op '${cond.op}'`);
275	    return true; // unknown op = pass (forward compat)
276	  }
277	
278	  private evaluateFilter(cond: RuleCondition, targetId: string, event: WorldEvent, ctx: WorldContext): boolean {
279	    const agent = ctx.agents.get(targetId);
280	    if (!agent) return false;
281	
282	    if (cond.op === 'has_capability') {
283	      const capFlag = (cond.value ?? cond.field) as string;
284	      return !!(agent.profile as unknown as Record<string, unknown>)[capFlag];
285	    }
286	    if (cond.op === 'trait') {
287	      return this.checkTrait(agent, cond);
288	    }
289	    if (cond.op === 'relationship') {
290	      const towardId = this.resolveToward(cond.toward!, event, ctx, targetId);
291	      return towardId ? this.checkRelationship(agent, towardId, cond) : false;
292	    }
293	    if (cond.op === 'belief') {
294	      return this.checkBelief(agent, event, cond);
295	    }
296	
297	    return true; // unknown filter = include (forward compat)
298	  }
299	
300	  // ─── CG v2: Helper functions ───
301	
302	  private resolveActor(ref: string, event: WorldEvent, ctx: WorldContext): Agent | null {
303	    const id = ref === 'subject' ? event.subject
304	      : ref === 'object' ? event.object
305	      : null;
306	    return id ? ctx.agents.get(id) ?? null : null;
307	  }
308	
309	  private resolveToward(ref: string, event: WorldEvent, ctx: WorldContext, targetId?: string): string | null {
310	    if (ref === 'subject') return event.subject;
311	    if (ref === 'object') return event.object ?? null;
312	    if (ref === 'target') return targetId ?? null;
313	    // Payload field → may be NPC name, resolve to ID
314	    const nameOrId = event.payload?.[ref] as string | undefined;
315	    if (!nameOrId) return null;
316	    if (ctx.agents.has(nameOrId)) return nameOrId;
317	    for (const [id, a] of ctx.agents) {
318	      if (a.profile.name === nameOrId) return id;
319	    }
320	    return null;
321	  }
322	
323	  private checkTrait(agent: Agent, cond: RuleCondition): boolean {
324	    const traitName = cond.trait as string;
325	    const traitValue = (agent.profile.bigFive as unknown as Record<string, number>)[traitName];
326	    if (traitValue == null) return false;
327	    return this.compare(traitValue, cond.comparator ?? '>', cond.value as number);
328	  }
329	
330	  private checkRelationship(agent: Agent, towardId: string, cond: RuleCondition): boolean {
331	    const rel = agent.state.relationships?.getRelationship(towardId);
332	    if (!rel) return false;
333	    const val = (rel as unknown as Record<string, number>)[cond.field ?? 'sentiment'];
334	    if (val == null) return false;
335	    return this.compare(val, cond.comparator ?? '>', cond.value as number);
336	  }
337	
338	  private checkBelief(agent: Agent, event: WorldEvent, cond: RuleCondition): boolean {
339	    if (!agent.state.beliefs) return false;
340	    const beliefs = agent.state.beliefs.getAllBeliefs();
341	    return beliefs.some(b => {
342	      if (cond.eventType && b.eventType !== cond.eventType) return false;
343	      if (cond.minConfidence && b.confidence < cond.minConfidence) return false;
344	      if (cond.aboutSubject && b.subject !== ((event.payload?.perpetratorName as string) ?? event.subject)) return false;
345	      return true;
346	    });
347	  }
348	
349	  private compare(a: number, op: string, b: number): boolean {
350	    switch (op) {
351	      case '>': return a > b;
352	      case '<': return a < b;
353	      case '>=': return a >= b;
354	      case '<=': return a <= b;
355	      default: return a === b;
356	    }
357	  }
358	
359	  // ─── Belief & Memory (unchanged from v1) ───
360	
361	  private createBelief(
362	    rule: ConsequenceRule,
363	    event: WorldEvent,
364	    targetId: string,
365	    ctx: WorldContext,
366	  ): void {
367	    const agent = ctx.agents.get(targetId);
368	    if (!agent?.state.beliefs) return;
369	
370	    // Resolve perpetrator/victim to agent IDs for belief fields (INV-11: internal = ID, display = name)
371	    const perpetratorName = (event.payload?.perpetratorName as string) ?? null;
372	    const suspectId = perpetratorName
373	      ? (Array.from(ctx.agents.entries()).find(([, a]) => a.profile.name === perpetratorName)?.[0] ?? perpetratorName)
374	      : event.subject ?? null;
375	    const affectedId = event.object ?? null;
376	    const crimeEventType = (event.payload?.originalEventType as string) ?? event.type;
377	
378	    const creator = getBeliefCreator(rule.consequence.type);
379	    if (creator) {
380	      creator(agent, event, rule, crimeEventType, suspectId, affectedId);
381	    }
382	  }
383	
384	  private buildMemoryText(
385	    rule: ConsequenceRule,
386	    event: WorldEvent,
387	    _targetId: string,
388	    ctx: WorldContext,
389	  ): string {
390	    const suspect = (event.payload?.perpetratorName as string) ?? 'someone unknown';
391	    const victim = event.object ? ctx.agents.get(event.object) : null;
392	    const affectedName = (event.payload?.affectedName as string)
393	      ?? (victim ? victim.profile.name : null)
394	      ?? event.object ?? 'someone';
395	
396	    const builder = getMemoryTextBuilder(rule.consequence.type);
397	    if (builder) return builder(event, suspect, affectedName);
398	
399	    console.warn(`[CG] No memory text builder for consequence type: ${rule.consequence.type}`);
400	    return `Something significant happened involving ${suspect}.`;
401	  }
402	}
